window.ACADEMY={"lessons":[{"id":"l1","cat":"Начало смены","title":"Открытие ПВЗ","summary":"Подготовка пункта к работе с клиентами и поставками.","steps":["Придите к началу смены и проверьте доступность помещения и оборудования.","Убедитесь, что рабочее место, клиентская зона и примерочные чистые.","Проверьте интернет, сканер, компьютер и работу камер наблюдения.","Авторизуйтесь в WB ПВЗ под своей учётной записью.","Проверьте актуальные уведомления, поставки и незавершённые операции."],"notes":"Не используйте чужие учётные данные. О проблемах, мешающих работе, сообщайте ответственному.","quiz":[{"q":"Что нужно проверить до начала выдачи?","options":["Только наличие пакетов","Камеры, оборудование, чистоту и рабочую программу","Только отзывы"],"answer":1}],"role":"Сотрудник","version":""},{"id":"l2","cat":"Начало смены","title":"Распорядок дня","summary":"Повторяющиеся действия в течение смены.","steps":["Принимайте поступающие поставки и размещайте товары по ячейкам.","Выдавайте заказы и оформляйте отказы строго через программу.","Следите за курьерскими заказами и возвратами.","Регулярно проверяйте примерочные, склад и клиентскую зону.","Проводите переупаковку и формируйте возвратные коробки по требованиям программы.","Перед закрытием проверьте незавершённые операции и состояние ПВЗ."],"notes":"Указанные действия дополняют, но не заменяют текущие задания в WB ПВЗ.","quiz":[],"role":"Сотрудник","version":""},{"id":"l3","cat":"Начало смены","title":"Чистота и порядок","summary":"Практический чек-лист уборки.","steps":["Мойте полы не менее двух раз в день с учётом загрязнения.","Протирайте коврики, зеркала и контактные поверхности ориентировочно каждые 2–3 часа.","Проверяйте примерочную после каждого клиента.","Убирайте влагу и грязь с учётом сезона.","Следите за состоянием штор, мебели и зоны выдачи."],"notes":"Периодичность взята из присланных учебных памяток; актуальные требования к состоянию ПВЗ сверяйте с регламентом.","quiz":[],"role":"Сотрудник","version":""},{"id":"l4","cat":"Начало смены","title":"Перерыв одного сотрудника","summary":"Как временно закрыть ПВЗ, если работаете в одиночку.","steps":["При необходимости краткого перерыва подготовьте объявление формата А4 с временем отсутствия.","Разместите объявление на видном месте под камерой.","Не превышайте предусмотренный инструкцией перерыв до 15 минут.","Вернувшись, снимите объявление и возобновите работу."],"notes":"Правило относится к описанному в обучающих материалах сценарию. Проверяйте актуальные ограничения.","quiz":[],"role":"Сотрудник","version":""},{"id":"l5","cat":"Начало смены","title":"Авторизация в WB ПВЗ","summary":"Безопасный вход в десктопное и мобильное приложение.","steps":["Войдите с привязанным номером телефона и подтвердите авторизацию доступным способом.","Выберите нужный ПВЗ и свою учётную запись сотрудника.","Установите или введите PIN, если приложение предлагает.","При переходе на другой ПВЗ переключите рабочий контекст.","При проблеме с входом используйте штатное восстановление или поддержку."],"notes":"Не передавайте коды, PIN и доступ третьим лицам.","quiz":[{"q":"Можно ли пользоваться PIN другого сотрудника?","options":["Да, если он разрешил","Нет","Да, если очередь"],"answer":1}],"role":"Сотрудник","version":""},{"id":"l6","cat":"Приёмка и склад","title":"Приёмка поставки","summary":"От получения коробки до размещения товара.","steps":["Примите поставку в рабочей программе, используя предусмотренное сканирование.","Проверяйте фактическое содержимое и маркировку в процессе приёмки.","Фиксируйте расхождения, повреждения и отсутствие товара через доступные функции.","Разместите принятые товары в ячейках и поддерживайте актуальность их расположения.","Сохраняйте возможность подтвердить действия видеозаписью с камер."],"notes":"Не подтверждайте получение товаров, которые фактически не поступили.","quiz":[],"role":"Сотрудник","version":""},{"id":"l7","cat":"Приёмка и склад","title":"Организация склада","summary":"Как быстро находить заказы и снижать потери.","steps":["Разделяйте хранение по предусмотренным ячейкам, полкам и зонам.","Сканируйте перемещение товара в ячейку, когда это предусмотрено программой.","Не закрывайте доступ к пожарным выходам и оборудованию.","Крупногабаритные товары размещайте отдельно по правилам.","Не смешивайте товары, подготовленные к возврату, с заказами к выдаче."],"notes":"","quiz":[],"role":"Сотрудник","version":""},{"id":"l8","cat":"Приёмка и склад","title":"Поиск товара по ШК","summary":"Как найти заказ через десктопную программу.","steps":["Введите или отсканируйте штрихкод товара в строке поиска.","Проверьте статус, факт приёмки и указанное место хранения.","Осмотрите соответствующую ячейку, соседние полки и возможные возвратные коробки.","Если товар не найден, зафиксируйте проблему штатным способом."],"notes":"Не выдавайте и не возвращайте товар, пока не выяснен его фактический статус.","quiz":[],"role":"Сотрудник","version":""},{"id":"l9","cat":"Приёмка и склад","title":"Инвентаризация","summary":"Проверка фактических остатков.","steps":["Запустите инвентаризацию в доступной версии WB ПВЗ.","Последовательно просканируйте все товары, числящиеся на ПВЗ.","Разберите расхождения и найдите неотсканированные позиции.","Завершите проверку в установленный срок."],"notes":"В присланных материалах: инвентаризация не реже раза в 30 дней; на завершение отводится 24 часа. Сверяйте с актуальными правилами.","quiz":[{"q":"Что нужно сделать при инвентаризации?","options":["Просканировать только новые товары","Просканировать все товары, числящиеся в ПВЗ","Посчитать только коробки"],"answer":1}],"role":"Сотрудник","version":""},{"id":"l10","cat":"Выдача клиенту","title":"Обычная выдача заказа","summary":"Проверка клиента, товара и завершение операции.","steps":["Попросите клиентский QR-код либо используйте предусмотренный альтернативный способ идентификации.","Найдите товар и отсканируйте его в программе.","Покажите товар клиенту под камерой; обеспечьте возможность осмотра и примерки.","Проверьте в программе статус оплаты, возвратность и специальные ограничения.","Завершите выдачу только после подтверждения соответствующих действий в программе.","Предложите пакет, если он нужен, и поблагодарите клиента."],"notes":"Клиентский QR-код обновляется ежедневно; ориентируйтесь на актуальный код в приложении клиента.","quiz":[{"q":"Когда можно считать заказ выданным?","options":["Когда клиент взял коробку","После корректного завершения выдачи в программе","Когда клиент назвал имя"],"answer":1}],"role":"Сотрудник","version":""},{"id":"l11","cat":"Выдача клиенту","title":"Примерка и отказ","summary":"Как корректно снять товар с выдачи.","steps":["Проверьте, какие позиции клиент берёт на примерку.","После примерки уточните решение по каждому товару.","Для отказа используйте предусмотренную функцию снятия с выдачи.","При наличии брака или повреждения зафиксируйте соответствующую отметку.","Подготовьте отказанный товар к возврату по инструкции."],"notes":"Не путайте обычный отказ и товар, который система запрещает возвращать без специальных оснований.","quiz":[],"role":"Сотрудник","version":""},{"id":"l12","cat":"Выдача клиенту","title":"Неотказные и невозвратные товары","summary":"Разница между запретом отказа и домашним возвратом.","steps":["До завершения выдачи проверьте специальные ограничения в карточке товара.","Объясните клиенту правила, которые отображает система.","Если клиент заявляет о дефекте, действуйте по процедуре проверки брака и обращения клиента.","Не обещайте возврат или отказ, если система не разрешает его оформить."],"notes":"У разных категорий товаров правила различаются; решения принимайте по текущему статусу товара.","quiz":[],"role":"Сотрудник","version":""},{"id":"l13","cat":"Выдача клиенту","title":"Отмена заказа во время выдачи","summary":"Что делать со статусом «Ожидает отмены».","steps":["Проверьте системный статус заказа.","Если отображается «Ожидает отмены» или «Нельзя выдать», не выдавайте товар.","Не добавляйте его в возвратную коробку до решения системы.","После изменения статуса действуйте по доступной операции: возврат или размещение в ячейке."],"notes":"В десктопе статус виден в возвратах; в мобильном приложении — «Вернуть» → «Ждут отмены».","quiz":[],"role":"Сотрудник","version":""},{"id":"l14","cat":"Выдача клиенту","title":"Выдать товар из отказа","summary":"Сценарий, когда клиент передумал.","steps":["Проверьте, что с момента отказа прошло не более 24 часов.","Убедитесь, что товар ещё не помещён в закрытую возвратную коробку.","В десктопной программе используйте функцию «Выдать из отмены», если она доступна.","Проверьте статус и завершите выдачу штатным способом."],"notes":"Если система не предлагает операцию, не обходите ограничение вручную.","quiz":[],"role":"Сотрудник","version":""},{"id":"l15","cat":"Выдача клиенту","title":"Проблема с оплатой","summary":"Оплата не проходит или клиент ушёл с товаром.","steps":["Проверьте статус оплаты в программе; не считайте заказ оплаченным по словам клиента.","Если оплата не проходит повторно или клиент ушёл без оплаты, оформите предусмотренный тикет.","Подготовьте записи с камер, показывающие ситуацию.","Передайте ссылку на видео в установленный срок."],"notes":"В инструкции WB Point от 03.10.2025 для тикета «Проблема с оплатой» указан срок предоставления доказательств 24 часа.","quiz":[],"role":"Сотрудник","version":""},{"id":"l16","cat":"Выдача клиенту","title":"Подарочные сертификаты","summary":"Приёмка и выдача особой категории.","steps":["Примите сертификаты по предусмотренной схеме.","При выдаче отсканируйте соответствующие коды и идентификатор клиента.","Проверьте особый порядок выдачи в десктопной или мобильной программе.","Не обещайте обналичивание, отказ или возврат вне правил системы."],"notes":"","quiz":[],"role":"Сотрудник","version":""},{"id":"l17","cat":"Возвраты","title":"Возврат товара из дома","summary":"Как принять клиентский возврат.","steps":["Попросите QR возврата из клиентского приложения.","Определите тип QR: общий для заказов или конкретного товара.","При общем QR дополнительно отсканируйте ШК возвращаемого товара.","При предметном QR сравните товар с карточкой и заявкой клиента.","Проверьте состояние, комплектность, маркировку и возможное одобрение заявки по браку.","Подтвердите приём только при соответствии правилам."],"notes":"В десктопе: «Возврат» → «Товары» → «Возврат от клиента»; в мобильном: «Вернуть» → «Принять возврат от клиента».","quiz":[],"role":"Сотрудник","version":""},{"id":"l18","cat":"Возвраты","title":"Возврат без штрихкода","summary":"Что делать, если на товаре нет ШК.","steps":["Откройте предусмотренную в десктопе функцию «На товаре нет ШК».","Найдите подходящую позицию среди доступных недавних заказов или одобренных заявок.","Сравните характеристики товара с карточкой и заявкой.","Следуйте подсказкам системы для оформления и маркировки."],"notes":"В инструкции 2025 года описано написание ШК на бумаге; этот шаг требует сверки с актуальным интерфейсом.","quiz":[],"role":"Сотрудник","version":""},{"id":"l19","cat":"Возвраты","title":"Возвратная коробка","summary":"Как сформировать и передать коробку на склад.","steps":["Создайте возвратную коробку и сканируйте товары в неё по правилам программы.","Убедитесь, что товар физически находится в той коробке, куда записан в системе.","Не смешивайте крупногабаритные товары с обычными возвратами.","Закройте коробку, закрепите читаемый TRBX и покажите маркировку камере.","Передайте коробку уполномоченному водителю по процедуре."],"notes":"В присланных инструкциях: не более 3 открытых коробок, до 60 товаров в одной. Сроки закрытия и передачи могут зависеть от сценария.","quiz":[{"q":"Какой код должен быть на возвратной коробке?","options":["Любой старый ШК","Один актуальный TRBX","Все старые штрихкоды"],"answer":1}],"role":"Сотрудник","version":""},{"id":"l20","cat":"Возвраты","title":"Правильная маркировка TRBX","summary":"Как избежать ошибки сканирования коробки.","steps":["Оставьте на коробке только актуальную читаемую этикетку TRBX.","Удалите или закройте старые читаемые штрихкоды.","Не заклеивайте термоэтикетку скотчем поверх печати.","Если этикетка утрачена, восстановите QR по идентификатору TRBX и номеру предусмотренным способом."],"notes":"Пример структуры: TRBX + номер коробки. Не подставляйте выдуманный номер.","quiz":[],"role":"Сотрудник","version":""},{"id":"l21","cat":"Возвраты","title":"Переупаковка товара","summary":"Подготовка отказа к отправке на склад.","steps":["Сверьте товар с карточкой: артикул, размер, цвет, бренд, комплектность и состояние.","Используйте подходящий пакет и зарегистрированный стикер, назначенный программой.","Сохраните обязательную маркировку, включая «Честный знак».","Уберите лишние читаемые коды, не относящиеся к текущему товару.","Поместите товар в коробку и закройте упаковку в правильной последовательности."],"notes":"Для КГТ может использоваться сценарий «Без упаковки». Не переупаковывайте повреждённые и неподходящие товары как исправные.","quiz":[],"role":"Сотрудник","version":""},{"id":"l22","cat":"Возвраты","title":"Регистрация рулонов стикеров","summary":"Как активировать наклейки для переупаковки.","steps":["В десктопном приложении откройте «Наклейки для работы с товаром».","Перейдите в «Регистрация рулонов с наклейками».","Отсканируйте первый стикер рулона с минимальным номером.","Отсканируйте второй стикер — следующий по номеру.","Отсканируйте последний стикер с максимальным номером.","Дождитесь подтверждения регистрации."],"notes":"Рулон, зарегистрированный на другом ПВЗ, может быть отклонён. Используйте только зарегистрированные наклейки.","quiz":[],"role":"Сотрудник","version":""},{"id":"l23","cat":"Возвраты","title":"Возврат картона","summary":"Что делать с пустыми коробками.","steps":["Соберите подлежащий возврату картон и удалите старые наклейки.","Укажите количество и оформите возврат картона через рабочую программу.","Передайте подготовленный картон водителю.","Если водитель не забирает возврат, оформите логистическое обращение с подтверждением."],"notes":"В обучающих материалах указаны исключения для авиа- и железнодорожной логистики. После создания возврата количество картона может быть недоступно для изменения.","quiz":[],"role":"Сотрудник","version":""},{"id":"l24","cat":"Возвраты","title":"Утилизация товаров","summary":"Как списывать товары, назначенные в утиль.","steps":["Откройте в десктопном WB ПВЗ «Возврат» → «Утиль».","Выберите или отсканируйте позиции, доступные для утилизации.","Нажмите «Утилизировать» и подтвердите операцию.","Удалите брендинг и маркировку Wildberries перед физической утилизацией."],"notes":"Нельзя самостоятельно отправлять в утиль товары, которых нет в соответствующем списке.","quiz":[],"role":"Сотрудник","version":""},{"id":"l25","cat":"Брак и безопасность","title":"Проверка товара на брак","summary":"Как отличить дефект от допустимой особенности.","steps":["Осмотрите товар и упаковку под камерой.","Проверьте комплектность, швы, фурнитуру, поверхности, запахи и загрязнения.","Отличайте устранимую грязь на внешней упаковке от повреждения самого товара.","При выявленном дефекте выберите корректный тип брака и степень повреждения.","Сделайте необходимые фото и комментарий, если программа их запрашивает."],"notes":"Для подтверждения брака в присланных памятках указаны четыре фото: спереди, сзади, ШК и крупный план дефекта.","quiz":[{"q":"Что из перечисленного обычно является браком?","options":["Легко удаляемая пыль на внешней упаковке","Разрыв шва изделия","Незначительная складка транспортной упаковки"],"answer":1}],"role":"Сотрудник","version":""},{"id":"l26","cat":"Брак и безопасность","title":"Подмена товара","summary":"Порядок действий при подозрении на подмену.","steps":["Зафиксируйте фактический товар и его признаки под камерой.","Не смешивайте его с другими товарами и не скрывайте расхождение.","Отметьте проблему штатным способом в программе.","Сохраните видео приёмки, выдачи, отказа, упаковки и передачи возврата.","При удержании используйте соответствующее оспаривание в WB Point."],"notes":"Для оспаривания удержания за подмену в инструкции 2025 года указан срок 7 дней и только одна возможность по конкретному ШК.","quiz":[],"role":"Сотрудник","version":""},{"id":"l27","cat":"Брак и безопасность","title":"Зависшие ШК","summary":"Пошаговая диагностика товара без движения в системе.","steps":["Проверьте, был ли товар фактически принят в ПВЗ.","Поищите товар на полках, в соседних ячейках и возвратных коробках.","Если товар найден, проверьте его статус и назначение: возврат, утиль, поставщик.","Если он не принят — выполните приёмку, если операция доступна; затем оформите возврат.","Если товар отправлен в другой коробке, оформите тикет с номером коробки и доказательствами.","При удержании за непоступивший товар соберите непрерывные записи и оспорьте в срок."],"notes":"Оспаривание — в течение 7 дней; ответ на запрос поддержки — в течение 48 часов. Видео с камер хранить минимум 90 дней в РФ.","quiz":[{"q":"Что делать, если зависший товар найден на полке?","options":["Выдать без программы","Проверить статус и оформить движение по правилам","Выбросить"],"answer":1}],"role":"Сотрудник","version":""},{"id":"l28","cat":"Брак и безопасность","title":"Пожарная безопасность","summary":"Основные запреты и действия по предотвращению риска.","steps":["Не загромождайте выходы и пути эвакуации.","Следите за исправностью розеток и электроприборов.","Не храните горючие материалы у источников нагрева.","Не допускайте курения и использования открытого огня в помещении.","Контролируйте наличие и состояние огнетушителей согласно регламенту."],"notes":"При признаках пожара прежде всего обеспечьте безопасность людей и вызовите экстренные службы.","quiz":[],"role":"Сотрудник","version":""},{"id":"l29","cat":"Курьерские заказы","title":"Подготовка курьерского заказа","summary":"Сборка заказа на доставку клиенту.","steps":["Откройте список курьерских заказов в WB ПВЗ.","Найдите позиции со статусом «Ожидает сборки».","Просканируйте товары и подтвердите их наличие.","Отметьте повреждённый ШК, ненайденный или повреждённый товар через штатные функции.","Подготовьте заказ к передаче курьеру под камерой."],"notes":"При позднем обнаружении товара до прихода курьера используйте предусмотренный сценарий восстановления.","quiz":[],"role":"Сотрудник","version":""},{"id":"l30","cat":"Курьерские заказы","title":"Выдача заказа курьеру","summary":"Проверка курьера и передача подготовленного заказа.","steps":["Попросите курьерский QR-код из «WB Курьер».","Откройте выдачу курьеру и просканируйте QR.","Проверьте подготовленные и неподготовленные позиции.","Подтвердите фактически переданные товары; при необходимости оформите частичную выдачу.","Выдайте предусмотренное системой количество пакетов."],"notes":"Курьер не должен вскрывать упаковку товаров. Для отдельных служб может применяться дополнительный код.","quiz":[],"role":"Сотрудник","version":""},{"id":"l31","cat":"Курьерские заказы","title":"Возврат заказа от курьера","summary":"Приём заказа, который не доставили клиенту.","steps":["Откройте приём возврата курьера в программе.","Просканируйте курьерский QR и фактически возвращённые товары.","Осмотрите вскрытые или повреждённые товары.","Отметьте отсутствующие позиции — не подтверждайте их как полученные.","Направьте принятый товар «На полку» или «В отказ» по статусу."],"notes":"Возврат курьерской доставки должен оформляться в том же ПВЗ, из которого заказ выдавался.","quiz":[],"role":"Сотрудник","version":""},{"id":"l32","cat":"Курьерские заказы","title":"Разбор курьерского заказа","summary":"Если заказ отменён до передачи курьеру.","steps":["Найдите заказ со статусом «Ожидает разборки».","Просканируйте позиции в процессе разбора.","Верните товары в предусмотренные ячейки.","Закончите разбор до окончания смены."],"notes":"","quiz":[],"role":"Сотрудник","version":""},{"id":"l33","cat":"Спецсервисы","title":"WB Track — приём посылки","summary":"Отправка клиентской посылки через ПВЗ.","steps":["Попросите клиента оформить отправление и показать QR в приложении.","Под камерой проверьте содержимое и отсутствие запрещённых предметов.","Проверьте упаковку и соответствие ограничениям по весу.","После подтверждения оплаты оформите посылку и поместите в отдельный сейф-пакет.","На каждый пакет наклейте собственный штрихкод отправления.","Сформируйте отдельную возвратную коробку для отправлений и передайте водителю."],"notes":"В присланных материалах: до 25 кг на посылку; не более 60 отправлений в коробке; один сейф-пакет — одна посылка.","quiz":[{"q":"Можно ли объединить две посылки в одном сейф-пакете под одним ШК?","options":["Да","Нет","Только если клиент один"],"answer":1}],"role":"Сотрудник","version":""},{"id":"l34","cat":"Спецсервисы","title":"WB Track — запрещённые вложения","summary":"Что нельзя принимать к отправке.","steps":["Откажите в приёме опасных, взрывоопасных и легковоспламеняющихся предметов.","Не принимайте оружие, наркотики, алкоголь и никотиновую продукцию.","Не принимайте наличные, документы личности, животных и растения.","Не принимайте скоропортящиеся продукты, жидкости и иные запрещённые категории.","Если клиент отказывается показать содержимое, не принимайте отправление."],"notes":"Полный актуальный перечень ограничений необходимо сверять с действующими правилами.","quiz":[],"role":"Сотрудник","version":""},{"id":"l35","cat":"Спецсервисы","title":"WB Ресейл — приём от продавца","summary":"Продажа вещей между клиентами WB.","steps":["Проверьте присутствие продавца и его QR.","Осмотрите товар и упаковку под камерой.","Определите способ отправки: WB Track либо WB МП.","Для WB Track оформите ресейл в разделе посылок и используйте предусмотренный код отправления.","Для WB МП проверьте наличие ШК товара и коробки WB МП.","Передайте товар в соответствующую коробку для вывоза."],"notes":"В присланных инструкциях для товара ресейл: до 5 кг, максимальная сторона 60 см, сумма сторон до 140 см. При WB Track дополнительный сейф-пакет поверх упаковки продавца не нужен.","quiz":[],"role":"Сотрудник","version":""},{"id":"l36","cat":"Спецсервисы","title":"WB Ресейл — выдача и возврат","summary":"Особенности заказа вторичной продажи.","steps":["При выдаче покупателю проверьте статус заказа и доступность отказа.","При отказе оформите возврат в программе.","Возвращённый продавцу товар выдавайте по специальному статусу.","Не оформляйте возврат ресейла из дома, если система не поддерживает такую операцию."],"notes":"В присланных материалах: хранение у покупателя 12 дней, возврат продавцу — 7 дней до утилизации. Проверяйте актуальность сроков.","quiz":[],"role":"Сотрудник","version":""},{"id":"l37","cat":"Спецсервисы","title":"Товары поставщика","summary":"Приём и выдача товаров, возвращённых поставщику.","steps":["Примите товары поставщика через «Приёмка» и разместите в ячейке.","При выдаче отсканируйте QR поставщика из его личного кабинета.","Проверьте список и фактическое количество товаров.","При необходимости оформите отказ поставщика от отдельных позиций штатной функцией."],"notes":"Не путайте этот сценарий с выдачей товаров партнёрских маркетплейсов.","quiz":[],"role":"Сотрудник","version":""},{"id":"l38","cat":"Спецсервисы","title":"Партнёрские маркетплейсы","summary":"Особый порядок выдачи сторонних товаров.","steps":["Примите поставку по предусмотренным QR и ШК.","При выдаче проверьте отметку партнёрского товара в программе.","Сканируйте товары и используйте предусмотренный код клиента.","Не оформляйте обычный отказ или возврат в ПВЗ, если это запрещено правилами партнёра."],"notes":"Порядок отличается от стандартной выдачи Wildberries и от товаров поставщика.","quiz":[],"role":"Сотрудник","version":""},{"id":"l39","cat":"Поддержка и штрафы","title":"Как создать тикет WB Point","summary":"Общий алгоритм обращения в поддержку.","steps":["Откройте WB Point → «Тикеты».","Выберите подходящую тему, ПВЗ и причину обращения.","Опишите факты: что произошло, когда, какие ШК или коробки затронуты.","Приложите нужные фото, видео и работающие ссылки.","Отправьте обращение и отслеживайте запросы специалиста."],"notes":"По инструкции 03.10.2025 ответ на запрос поддержки обычно нужен в течение 48 часов; для проблемы с оплатой — 24 часа.","quiz":[{"q":"Как лучше составить тикет?","options":["Написать «разберитесь»","Указать факты, время, ШК и доказательства","Отправить пустой тикет"],"answer":1}],"role":"Сотрудник","version":""},{"id":"l40","cat":"Поддержка и штрафы","title":"Оспаривание брака и подмены","summary":"Как подготовить доказательства.","steps":["Найдите удержание в соответствующем разделе WB Point.","Проверьте доступность кнопки «Оспорить».","Подготовьте видео приёмки, работы с клиентом, возврата в коробку и передачи водителю.","Укажите в комментарии, что видно на каждом фрагменте.","Отправьте обращение и отвечайте на запросы поддержки вовремя."],"notes":"В документах 2025 года указан срок 7 дней и однократность оспаривания по конкретному товару.","quiz":[],"role":"Сотрудник","version":""},{"id":"l41","cat":"Поддержка и штрафы","title":"Оспаривание оценки клиента","summary":"Как оспорить необоснованный отзыв.","steps":["Откройте рейтинг ПВЗ в WB Point.","Найдите оценку 1 или 2 звезды с доступной кнопкой оспаривания.","Нажмите «Оспорить»; тикет создаётся автоматически.","Проверьте, что запись работы с клиентом доступна в видеоархиве.","Дождитесь решения и уведомления."],"notes":"В инструкции 2025 года — 48 часов с появления оценки, один раз. Некоторые отзывы с пониженным весом оспаривать нельзя.","quiz":[],"role":"Сотрудник","version":""},{"id":"l42","cat":"Поддержка и штрафы","title":"Логистика и водитель","summary":"Жалобы, несвоевременная доставка и невывоз коробок.","steps":["В WB Point откройте «Тикеты» → «Вопросы по логистике».","Выберите причину: жалоба на водителя, удержание за приёмку, доставка, невывоз возвратов/картона, лимиты.","Укажите дату, время, номер коробки и фактическую ситуацию.","Приложите непрерывную запись с камер, подтверждающую проблему.","Следите за ответом и своевременно предоставляйте дополнения."],"notes":"Для жалобы на водителя видеоподтверждение обязательно по инструкции от 03.10.2025.","quiz":[],"role":"Сотрудник","version":""},{"id":"l43","cat":"Поддержка и штрафы","title":"Помощник WB ПВЗ","summary":"Как обратиться в чат и оценить ответ.","steps":["В десктопном WB ПВЗ нажмите значок сообщения справа вверху.","В мобильном WB ПВЗ откройте «Ещё» → «Помощник».","Опишите проблему и приложите необходимые данные.","После закрытия обращения оцените качество ответа в появившемся окне."],"notes":"Окно оценки появляется в течение двух часов после закрытия обращения.","quiz":[],"role":"Сотрудник","version":""},{"id":"l44","cat":"Поддержка и штрафы","title":"Видеодоказательства","summary":"Чек-лист перед оспариванием удержания.","steps":["Убедитесь, что на видео полностью видны товар, коробка и действия сотрудника.","Проверьте, что обзор не перекрыт человеком, стеллажом или другими предметами.","Используйте непрерывные записи с камер ПВЗ без склеек.","Проверьте даты, время, ссылки и доступ для просмотра.","Сохраните архив на необходимый срок."],"notes":"В инструкциях для РФ — не менее 90 дней, для Беларуси — 30 дней. Видео с телефона для таких оспариваний не принимаются.","quiz":[],"role":"Сотрудник","version":""},{"id":"l45","cat":"Поддержка и штрафы","title":"Какие тикеты бывают","summary":"Краткий навигатор по темам WB Point.","steps":["Удержания: «Зависшие ШК», «Подмены», «Брак».","Клиенты: «Недобросовестный клиент», «Оспаривание оценок», «Проблема с оплатой».","Техника: «Электронные замки», «Техподдержка десктопа».","ПВЗ: «Ремонт», «Аудит», «Низкий рейтинг», «График работы», «Смена собственника», «Субсидии».","Логистика: водитель, приёмка, доставка, возвратные коробки, лимиты."],"notes":"Часть тикетов доступна только собственнику. Список тем может изменяться.","quiz":[],"role":"Собственник / менеджер","version":""},{"id":"l46","cat":"Поддержка и штрафы","title":"Тикеты собственника","summary":"Операционные вопросы, доступные владельцу.","steps":["Для изменения графика выберите «График работы» и укажите причину с подтверждениями.","Для подключения приёмки МП выберите «Приёмка МП».","Для ремонта, аудита, субсидии или смены собственника используйте одноимённую тему.","Для подозрения на кражу сотрудником выберите «Чёрный список» и приложите запись и ШК.","Для проблем с работой ПВЗ выберите техническую тему и опишите воспроизводимые шаги."],"notes":"Для «Субсидий» в инструкции 2025 года указан мораторий 30 дней на повторное обращение.","quiz":[],"role":"Собственник","version":""},{"id":"n1","cat":"Потерянные товары","title":"Потерялся товар при выдаче","summary":"Статус «Утерян на ПВЗ» и 48 часов на поиск.","steps":["Если не находите товар при выдаче, используйте «Не могу найти» в карточке, если функция доступна.","Товар получит статус «Утерян на ПВЗ» и отметку «Надо найти»; его нельзя включить в выдачу.","На поиск даётся 48 часов; если это последний день хранения, срок продлевается на 2 дня.","Найденный товар повторно отсканируйте в «Приёмке» на ПК или «Принять» на телефоне.","Если за 48 часов товар не найден, согласно публикации его стоимость списывается с ПВЗ, заказ отменяется без влияния на процент выкупа и без обратной логистики."],"notes":"Функция первоначально запускалась в Москве; доступность проверяйте в своей версии приложения. Для QR-кода по ШК товара WB доступен бесплатный специализированный генератор в боте: t.me/edholod_wbbot.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Если не находите товар при выдаче, используйте «Не могу найти» в карточке, если функция доступна.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n2","cat":"Нестандартные ситуации","title":"Нет интернета: что работает","summary":"Приёмка и выдача в офлайне; возвраты только онлайн.","steps":["При нестабильной связи попробуйте доступный Wi-Fi.","В офлайн-режиме приложения WB ПВЗ поддерживаются приёмка и выдача товаров.","После восстановления интернета статусы синхронизируются; списание оплаты происходит автоматически согласно инструкции от 5 мая 2026.","Возвраты из дома, подготовка возвратов, возвратные коробки, операции WB MP в разделе возвратов, картон и утиль требуют интернета.","После восстановления связи проверьте статусы выполненных операций."],"notes":"Не переносите правила офлайн-работы на сторонние сервисы и WB Track без отдельного подтверждения.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["При нестабильной связи попробуйте доступный Wi-Fi.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n3","cat":"Расходные материалы","title":"Клиентские пакеты: выдача и учёт","summary":"Учитывайте каждый выданный пакет, контролируйте остатки.","steps":["При выдаче укажите в WB ПВЗ тип и количество выданных пакетов.","Если пакет выдан после завершения заказа, повторно отсканируйте QR-код клиента.","По опубликованному правилу — не более двух пакетов каждого типа: майка, средний и большой.","В новых версиях система учитывает фактические остатки; при нуле выбор недоступен.","Храните пакеты рядом со стойкой так, чтобы выдачу было удобно контролировать.","Если пакеты закончились и автозаказ не поступил, создайте тикет «Автоматический заказ пакетов»."],"notes":"Пакеты-майки поступают чаще; средние и большие зависят от наличия на складе.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["При выдаче укажите в WB ПВЗ тип и количество выданных пакетов.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n4","cat":"Поставки продавцов","title":"WB MP: приёмка от продавца","summary":"Отличайте WB MP от FBW и DBS.","steps":["Принимайте WB MP в присутствии продавца; каждый товар должен быть индивидуально упакован и промаркирован.","На каждой коробке должна быть наклейка WB MP, коробка заклеена со всех сторон.","Один товар — не более 25 кг; коробка с содержимым — не более 25 кг.","Каждая сторона коробки — не более 80 см, сумма трёх измерений — не более 140 см.","Количество товаров в коробке не ограничено, если остальные условия соблюдены.","Не применяйте устаревшие лимиты 5 кг на коробку и 500 ШК в день из более ранних новостей."],"notes":"При задержке вывоза и переполнении ПВЗ используйте тикет «Приёмка МП → Вывоз МП-коробок».","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Принимайте WB MP в присутствии продавца; каждый товар должен быть индивидуально упакован и промаркирован.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n5","cat":"Поставки продавцов","title":"WB MP: возвратная коробка TRBX","summary":"Общая коробка для разных продавцов, но отдельно от обычных возвратов.","steps":["Создайте отдельную возвратную коробку для WB MP; не смешивайте с возвратами покупателей.","На физическую коробку нанесите TRBX и сканируйте его до сканирования наклейки поставки WB MP.","Проверяйте каждый товар в присутствии продавца.","Допускается объединять поставки разных продавцов в одной коробке WB MP.","Одновременно можно создать не более трёх возвратных коробок WB MP.","При отгрузке водитель сканирует один TRBX для каждой коробки."],"notes":"Порядок относится именно к коробкам возврата WB MP, а не к внешней упаковке поставки продавца.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Создайте отдельную возвратную коробку для WB MP; не смешивайте с возвратами покупателей.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n6","cat":"Поставки продавцов","title":"WB MP: передача перевозчику","summary":"Проверяйте QR-код перевозчика при вывозе коробок.","steps":["В разделе «Отгрузка товаров» покажите QR-код перевозчику.","Убедитесь в своём присутствии, что перевозчик его отсканировал.","После подтверждения назначенного вывоза передайте коробки по штатному процессу."],"notes":"QR перевозчика не заменяет наклейку TRBX на возвратной коробке.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["В разделе «Отгрузка товаров» покажите QR-код перевозчику.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n7","cat":"Поставки продавцов","title":"FBW: приёмка коробок продавца","summary":"Приёмка FBW без вскрытия и сканирования каждого товара.","steps":["Продавец заранее оформляет поставку и маркирует коробки.","В присутствии продавца и под камерой отсканируйте WB-GI на транспортной накладной и QR каждой коробки.","Не вскрывайте коробки и не сканируйте каждую единицу товара: это не WB MP.","При несовпадении количества нажмите «Назад → Прервать»; продавец должен исправить число коробок в своём приложении.","После исправления начните сканирование заново с WB-GI.","Частичная приёмка не допускается: если продавец отказывается исправлять количество, не принимайте всю поставку."],"notes":"Функция запускалась поэтапно; ограничения из отсутствующих карточек не додумываем.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Продавец заранее оформляет поставку и маркирует коробки.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n8","cat":"Поставки продавцов","title":"DBS: товары от продавца","summary":"Продавец привозит товар в тот же ПВЗ, где его заберёт покупатель.","steps":["Отличайте DBS от WB MP: DBS — это доставка товара продавцом непосредственно в ПВЗ покупателя.","Принимайте заранее упакованные товары через предусмотренный процесс DBS в приложении.","Выдавайте клиенту и оформляйте возвраты в соответствии с отдельными инструкциями DBS."],"notes":"Точные экраны и исключения изучайте в соответствующих инструкциях; нельзя переносить алгоритм FBW или MP на DBS.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Отличайте DBS от WB MP: DBS — это доставка товара продавцом непосредственно в ПВЗ покупателя.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n9","cat":"Приёмка и возвраты","title":"Шины и отмена категории «Запрещённый к поставке товар»","summary":"Не отмечайте шины браком только из-за категории.","steps":["Категория «Запрещённый к поставке товар» убрана из процессов ПВЗ с июня 2026.","Шины принимайте как обычный товар; брак отмечайте только при фактическом дефекте.","Для возврата шины как КГТ снимите старый ШК-стикер и наклейте новый.","В программе выберите возвратную коробку, наклейте её стикер на шину; физически в коробку шину не кладите.","Не перекрывайте наклейками маркировку прослеживаемости."],"notes":"Это не отменяет отдельные запреты на вложения в WB Track. Для QR-кода по ШК товара WB доступен бесплатный специализированный генератор в боте: t.me/edholod_wbbot.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Категория «Запрещённый к поставке товар» убрана из процессов ПВЗ с июня 2026.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n10","cat":"Приёмка и возвраты","title":"Возврат в неповреждённом сейф-пакете","summary":"Не вскрывайте целый сейф-пакет без необходимости.","steps":["При целой упаковке не нужно открывать сейф-пакет и заменять его.","В возвратах выберите товар, отсканируйте старую наклейку и выберите «Возврат без упаковки».","Наклейте новую этикетку поверх старой, полностью закрыв прежний код, затем отсканируйте новую.","Поместите товар в возвратную коробку.","Если содержимое явно повреждено или рассыпалось, вскройте, отметьте фактический брак и отправьте по соответствующему возвратному процессу."],"notes":"Не путайте сохранение целого сейф-пакета с оформлением брака. Для QR-кода по ШК товара WB доступен бесплатный специализированный генератор в боте: t.me/edholod_wbbot.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["При целой упаковке не нужно открывать сейф-пакет и заменять его.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n11","cat":"Приёмка и возвраты","title":"Обувь: проверка и возврат","summary":"Проверяйте пару, коробку и правильную упаковку.","steps":["Проверьте обувь и коробку на дефекты и соответствие заказу.","Если всё цело, поместите обувь вместе с коробкой в новый сейф-пакет.","Если коробка не входит даже в самый большой сейф-пакет, закрепите крышку резинками или скотчем.","Зачеркните старый стикер, нанесите новый и подготовьте к возврату.","При фактическом дефекте отметьте брак и следуйте соответствующему процессу."],"notes":"","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Проверьте обувь и коробку на дефекты и соответствие заказу.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n12","cat":"Брак и подмены","title":"Запах как признак брака","summary":"Посторонний запах может быть основанием для отметки дефекта.","steps":["При приёмке, выдаче, возврате от курьера и подготовке к возврату обращайте внимание на нехарактерный запах товара.","Если запах свидетельствует о дефекте, выберите соответствующий тип брака.","При выявлении дефекта во время подготовки возврата оформите его как брак, а не как обычную подготовку."],"notes":"Не приравнивайте любой запах к доказанной подмене.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["При приёмке, выдаче, возврате от курьера и подготовке к возврату обращайте внимание на нехарактерный запах товара.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n13","cat":"Брак и подмены","title":"Бренд не совпадает: это не всегда подмена","summary":"Несовпадение бренда само по себе не доказывает подмену.","steps":["Сравните бренд на товаре, упаковке и в карточке заказа.","Проверьте наличие пометки «Оригинал» и другие доступные признаки.","Не ставьте отметку «Подмена» исключительно из-за различия названий брендов.","При подтверждённом несоответствии действуйте по официальному алгоритму."],"notes":"Дополнительные критерии из карточек новости не представлены.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Сравните бренд на товаре, упаковке и в карточке заказа.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n14","cat":"Брак и подмены","title":"Бракованные товары: специальные коробки","summary":"Тестовая функция возвратных коробок для брака.","steps":["В подключённых ПВЗ коробка для брака может оставаться открытой до 6 дней.","Закройте её раньше, если набралось 10 ШК или коробка заполнена.","По истечении 6 дней предусмотрено автоматическое закрытие.","Пока коробка открыта, по условиям теста не формируются «Зависшие ШК» и удержания из-за её открытого статуса.","Крупногабаритный брак оформляйте отдельной коробкой: сохраните упаковку, наклейте новый стикер, сразу закройте и отправьте."],"notes":"Пилотный функционал: не распространяйте его автоматически на все ПВЗ.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["В подключённых ПВЗ коробка для брака может оставаться открытой до 6 дней.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n15","cat":"Брак и подмены","title":"Отметку брака поставили случайно","summary":"Как отменить незавершённую отметку о браке.","steps":["На ПК: «Возврат → Товары → карточка → Дополнить / снять брак → Нет → подтверждение».","На телефоне: «Вернуть → три точки рядом с товаром → Снять отметку брака → Да, отменить».","Отменить можно только частично оформленную отметку; завершённую — нельзя этим способом.","Для возвратов из дома с одобренным заявлением о браке действует другой порядок."],"notes":"После снятия ошибочной отметки можно продолжить обычную подготовку к возврату.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["На ПК: «Возврат → Товары → карточка → Дополнить / снять брак → Нет → подтверждение».","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n16","cat":"Выдача заказов","title":"IMEI смартфонов при выдаче и возврате","summary":"Проверка IMEI Apple/Samsung от 40 000 ₽ в рамках запуска.","steps":["Если программа предлагает проверку IMEI, сначала получите согласие клиента.","На ПК используйте «Проверить» или «Клиент отказался»; на телефоне — соответствующие варианты «Проверить все», «Проверить некоторые», «Клиент отказался».","До передачи клиенту сфотографируйте закрытый сейф-пакет, если это требуется процессом.","Не вскрывайте упаковку за клиента; осмотр проводите под камерой, не активируя смартфон до покупки.","При расхождении IMEI фиксируйте код на упаковке до вскрытия и код на экране после вскрытия.","При возврате из дома проверяйте IMEI и сброс до заводских настроек; если сброс не сделан, верните устройство клиенту для сброса."],"notes":"В июле 2026 функция запускалась для Apple и Samsung стоимостью от 40 000 ₽; перечень может изменяться.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Если программа предлагает проверку IMEI, сначала получите согласие клиента.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n17","cat":"Выдача заказов","title":"Товары «Не требует проверки»","summary":"Экспериментальный упрощённый процесс для отдельных товаров.","steps":["Если программа показывает «Не требует проверки», дополнительная проверка на камеру перед примеркой/покупкой не требуется.","Для некоторых клиентов отображается значок золотой звезды — это отдельный признак доступности упрощённых возвратов.","При отказе после примерки оформляйте фактический брак или подмену корректно, если они есть.","Для электроники, красоты и ювелирных изделий продолжает применяться «Требует проверки» согласно публикации."],"notes":"Тестовый режим: следуйте подсказкам конкретного заказа, не распространяйте на весь ассортимент.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Если программа показывает «Не требует проверки», дополнительная проверка на камеру перед примеркой/покупкой не требуется.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n18","cat":"Выдача заказов","title":"Проверка возраста через MAX","summary":"Цифровой ID как один из способов подтверждения 18+.","steps":["При выдаче товара 18+ программа покажет запрос подтверждения возраста.","Клиент может предъявить допустимый документ или цифровой ID в MAX.","Зелёная подсказка означает, что возраст подтверждён и товар 18+ можно выдать.","При неподтверждённом возрасте товары 18+ снимаются с выдачи, остальные товары можно выдать.","Если в заказе есть неотказные товары 18+, снимите весь заказ с примерки и предложите вернуться с документом до окончания хранения.","Отказные товары 18+ уходят в отмену; согласно публикации их можно забрать в течение 24 часов, если они ещё не в возвратной коробке.","При ошибке QR MAX повторите сканирование или используйте другой допустимый способ проверки."],"notes":"Список допустимых документов был в карточках и здесь не приводится.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["При выдаче товара 18+ программа покажет запрос подтверждения возраста.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n19","cat":"Выдача заказов","title":"Старый QR-код покупателя","summary":"Ошибка «Неизвестное отсканированное значение».","steps":["Если QR клиента не считывается и программа сообщает «Неизвестное отсканированное значение», попросите обновить клиентское приложение Wildberries.","Попросите показать новый QR-код и отсканируйте его повторно.","Если обновить приложение не удаётся, предложите прийти позднее."],"notes":"Номера минимальных версий из старых новостей не считаем актуальными.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Если QR клиента не считывается и программа сообщает «Неизвестное отсканированное значение», попросите обновить клиентское приложение Wildberries.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n20","cat":"Выдача заказов","title":"Выдача перед закрытием","summary":"Клиента, пришедшего за пять минут до закрытия, нужно обслужить.","steps":["Если клиент пришёл за 5 минут до закрытия в рабочее время, примите его.","Обеспечьте предусмотренные действия: выдачу, проверку, примерку и отказ.","Не отказывайте в обслуживании только потому, что до закрытия осталось мало времени."],"notes":"Не утверждаем конкретную обязательную длительность работы после закрытия: она не указана в новости.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Если клиент пришёл за 5 минут до закрытия в рабочее время, примите его.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n21","cat":"Дополнительные услуги","title":"Физические подарочные сертификаты","summary":"Приёмка, хранение, выдача и тестовое пополнение.","steps":["Сертификаты поступают как расходные материалы; при приёмке сканируйте ШК на упаковке с картами.","Сертификат состоит из пластиковой карты и подарочного конверта.","Несколько конвертов можно разместить у стойки; карты и остальные конверты храните отдельно.","При выдаче вложите карту в конверт; заклеивать его не требуется.","Пополнение физического сертификата в ПВЗ запускалось как тест в Москве, области, Санкт-Петербурге и Ленинградской области только для подключённых точек."],"notes":"Цена 50 ₽ указана на 2 июня 2026 и может измениться; шаги пополнения были только в карточках.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Сертификаты поступают как расходные материалы; при приёмке сканируйте ШК на упаковке с картами.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n22","cat":"Приёмка и возвраты","title":"Утилизация: товар уже отсутствует","summary":"Как закрыть позицию в разделе «Утиль».","steps":["Если товар уже физически выведен из оборота, но продолжает числиться в программе, завершите операцию.","На ПК: «Возврат → Утиль → галочка на карточке → Утилизировать → Подтвердить».","На телефоне: «Ждут утилизации», затем аналогичные действия.","Не используйте операцию для списания физически присутствующего товара без законного основания."],"notes":"Для QR-кода по ШК товара WB доступен бесплатный специализированный генератор в боте: t.me/edholod_wbbot.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Если товар уже физически выведен из оборота, но продолжает числиться в программе, завершите операцию.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n23","cat":"Поддержка и безопасность","title":"Поддержка: тикеты и «Помощник»","summary":"Уведомления, оценки и ответы бота.","steps":["Об ответе в тикете или чате «Помощник» сообщает уведомление «Вам сообщение».","Через 2 часа после ответа может прийти уведомление «Поставьте оценку».","После оценки можно оставить комментарий до 200 символов.","На тикеты отвечают как операторы, так и бот-помощник.","Проверяйте, решает ли ответ проблему, и при необходимости продолжайте обращение доступным способом."],"notes":"Ответ бота не означает автоматического разрешения спорной ситуации.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Об ответе в тикете или чате «Помощник» сообщает уведомление «Вам сообщение».","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n24","cat":"Поддержка и безопасность","title":"Оспаривание оценки 1–2","summary":"Важны 48 часов и положительное решение по обращению.","steps":["Оценки 1 и 2 первые 48 часов имеют нулевой вес согласно новости от 26 июня.","Чтобы избежать влияния оценки, подайте тикет на оспаривание в пределах 48 часов.","Одной подачи тикета недостаточно: оспаривание должно быть удовлетворено."],"notes":"Учитывайте возможные изменения сроков в актуальной оферте.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Оценки 1 и 2 первые 48 часов имеют нулевой вес согласно новости от 26 июня.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n25","cat":"Поддержка и безопасность","title":"Защита от мошенников","summary":"Не доверяйте внешним ссылкам и запросам кодов.","steps":["Покупки, доставку и возвраты оформляйте через официальный сайт или приложение WB.","Не сообщайте СМС-коды, паспортные данные и реквизиты карт посторонним.","Не переходите по ссылкам из подозрительных сообщений и не оплачивайте заказы по внешним ссылкам.","Не переводите обсуждение заказа в сторонние мессенджеры по просьбе неизвестных.","Акции проверяйте в официальных сервисах, вакансии — на career.rwb.ru."],"notes":"Пять схем из карточек публикации не воспроизводим: карточки не предоставлены.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Покупки, доставку и возвраты оформляйте через официальный сайт или приложение WB.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n26","cat":"Дополнительные услуги","title":"WB Track: ограничения и возвраты","summary":"Отдельные правила доставки WB Track.","steps":["Максимальная масса отправления WB Track по публикации — 15 кг.","Отправление должно помещаться в самый большой сейф-пакет; крупногабаритные вложения не принимаются.","Возвратная коробка WB Track создаётся на завершающем этапе приёмки отправления, отдельно её не создают.","При повреждении в пути клиент оформляет заявку в приложении WB в разделе «Возврат товара» с описанием и фотографиями."],"notes":"Не переносите эти правила на обычные заказы и поставки WB MP.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Максимальная масса отправления WB Track по публикации — 15 кг.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n27","cat":"Расходные материалы","title":"Наклейки: регистрация рулонов","summary":"Учёт рулонов и работа с повреждёнными стикерами.","steps":["Если в вашем ПВЗ включена регистрация рулонов, откройте соответствующий раздел в WB ПВЗ.","Рулон привязывается к ПВЗ, чтобы избежать дублирования наклеек между пунктами.","Если регистрационный стикер повреждён, используйте два соседних читаемых стикера.","Повреждённую наклейку при работе пропустите.","Если рулон частично использован, для регистрации предусмотрены первый, второй и последний оставшиеся стикеры."],"notes":"В июне регистрация была добровольной; не утверждаем, что это актуально сегодня.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["Если в вашем ПВЗ включена регистрация рулонов, откройте соответствующий раздел в WB ПВЗ.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n28","cat":"Приёмка и возвраты","title":"Работа с возвратными коробками","summary":"Перемещение излишков между открытыми коробками.","steps":["В мобильной версии можно переместить излишек между открытыми возвратными коробками.","Для одного излишка допускается не более двух перемещений согласно обновлению июня 2026.","Следите, чтобы операция была завершена в программе и товар находился в нужной физической коробке."],"notes":"","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["В мобильной версии можно переместить излишек между открытыми возвратными коробками.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n29","cat":"Начало смены","title":"Тайм-менеджмент в ПВЗ","summary":"Работа с очередью и прерываниями.","steps":["При очереди обслуживайте клиентов последовательно, не пытайтесь одновременно вести несколько выдач.","Если задачу пришлось прервать, зафиксируйте текущий статус и следующее действие.","Пример записи: «Сделать фото брака» или «В процессе».","Возвращайтесь к незавершённым операциям после устранения срочного прерывания."],"notes":"Основано на материалах корпоративного обучения RWB.","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["При очереди обслуживайте клиентов последовательно, не пытайтесь одновременно вести несколько выдач.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""},{"id":"n30","cat":"Полезные инструменты","title":"QR-код товара WB: полезный инструмент","summary":"Бесплатный специализированный генератор QR по штрихкоду товара WB.","steps":["В Telegram-боте «Всё о WB PVZ by @edholod» есть отдельный бесплатный генератор QR-кодов по штрихкодам товаров Wildberries.","Это именно специализированный генератор товарных QR, а не универсальный расширенный генератор.","Используйте его как вспомогательный инструмент при работе со штрихкодами и поиске товаров.","Не заменяйте официальные стикеры, маркировку и обязательные операции программы самодельными кодами, если это не предусмотрено правилами."],"notes":"Откройте бот: https://t.me/edholod_wbbot","quiz":[{"q":"Как правильно действовать в этой ситуации?","options":["В Telegram-боте «Всё о WB PVZ by @edholod» есть отдельный бесплатный генератор QR-кодов по штрихкодам товаров Wildberries.","Игнорировать подсказки приложения и не фиксировать операцию","Оформить операцию без проверки фактического товара"],"answer":0}],"role":"Сотрудник","version":""}],"scenarios":[{"title":"Товар не находится на полке","tag":"Поиск","steps":["Проверьте статус и ячейку по ШК","Осмотрите соседние ячейки и возвратные коробки","Не подтверждайте выдачу отсутствующего товара","Если проблема не решена — оформите предусмотренное обращение"],"lesson":"l8"},{"title":"Клиент передумал после отказа","tag":"Выдача","steps":["Проверьте срок 24 часа","Убедитесь, что товар не упакован в закрытую коробку","Используйте «Выдать из отмены», если функция доступна"],"lesson":"l14"},{"title":"Клиент отменил заказ на примерке","tag":"Выдача","steps":["Проверьте статус «Нельзя выдать»","Не выдавайте и не возвращайте до решения системы","После изменения статуса действуйте по программе"],"lesson":"l13"},{"title":"Не привезли товар со склада","tag":"Зависшие ШК","steps":["Подготовьте видео прибытия и вскрытия коробки, приёмки и пустой коробки","Оспорьте удержание в течение 7 дней","Ответьте на запрос поддержки в течение 48 часов"],"lesson":"l27"},{"title":"Водитель не забрал возврат","tag":"Логистика","steps":["Зафиксируйте коробки и факт невывоза на камеру","Откройте «Вопросы по логистике»","Выберите тему «Не забирают возвратные коробки/картон»"],"lesson":"l42"},{"title":"Обнаружен брак или подмена","tag":"Брак","steps":["Зафиксируйте состояние и расхождения под камерой","Отметьте проблему в программе","Сохраните записи для возможного оспаривания"],"lesson":"l25"},{"title":"Курьер вернул не все товары","tag":"Курьер","steps":["Просканируйте только реально возвращённые позиции","Не отмечайте отсутствующие товары принятыми","Оформите расхождение штатным способом"],"lesson":"l31"},{"title":"Клиент ушёл без оплаты","tag":"Оплата","steps":["Проверьте статус заказа","Создайте тикет «Проблема с оплатой»","Передайте видеодоказательства в течение 24 часов"],"lesson":"l15"},{"title":"Товар не найден при выдаче","tag":"Потеряшки","steps":["Проверьте ячейку и соседние места","При наличии кнопки «Не могу найти» установите статус","Продолжайте поиск до 48 часов","Если найдёте, повторно примите товар сканированием"],"lesson":"n1"},{"title":"Отключился интернет","tag":"Сбой связи","steps":["Проверьте доступность Wi-Fi","Продолжайте приёмку и выдачу в офлайн-режиме WB ПВЗ","Отложите операции возвратов до появления связи","После восстановления проверьте синхронизацию"],"lesson":"n2"},{"title":"Продавец привёз FBW с неверным числом коробок","tag":"FBW","steps":["Не принимайте часть коробок","«Назад → Прервать»","Попросите продавца исправить количество","Повторите сканирование с WB-GI"],"lesson":"n7"},{"title":"Клиент без паспорта покупает 18+","tag":"Возраст","steps":["Предложите подтверждение допустимым документом или цифровым ID MAX","Если возраст не подтверждён, не выдавайте 18+","Остальные товары выдайте, если это допускает процесс","Учтите отдельное правило для неотказных 18+"],"lesson":"n18"},{"title":"Закончились пакеты","tag":"Расходники","steps":["Проверьте остатки и учёт выдачи","Если автозаказ не поступил, создайте тикет «Автоматический заказ пакетов»","Продолжайте отмечать фактическую выдачу пакетов"],"lesson":"n3"},{"title":"Нужно получить QR по штрихкоду WB","tag":"Инструменты","steps":["Откройте Telegram-бот «Всё о WB PVZ by @edholod»","Выберите специализированный генератор товарных QR WB","Не заменяйте обязательную официальную маркировку самодельным кодом"],"lesson":"n29"}]};